/// <mls fileReference="_102047_/l2/controleEstoque/web/shared/produtos.ts" enhancement="_102020_/l2/enhancementAura"/>

import { property } from 'lit/decorators.js';
import { StateLitElement } from '/_102029_/l2/stateLitElement.js';
import { execBff } from '/_102029_/l2/bffClient.js';
import { getState, setState, subscribe, unsubscribe } from '/_102029_/l2/collabState.js';
import { runBlockingUiAction } from '/_102029_/l2/interactionRuntime.js';
import { auraNavigate } from '/_102033_/l2/shared/layout/auraNavigate.js';
import type { ProdutosContracts, ProdutoLoad, ProdutoCadastrarProduto } from '/_102047_/l2/controleEstoque/web/contracts/produtos.defs.js';
export type { ProdutosContracts, ProdutoLoad, ProdutoCadastrarProduto } from '/_102047_/l2/controleEstoque/web/contracts/produtos.defs.js';

type Route = keyof ProdutosContracts;
type Input<R extends Route> = ProdutosContracts[R]['input'];
type Output<R extends Route> = ProdutosContracts[R]['output'];

export type ErrorState = { code: string; message: string; details?: unknown } | null;
export type RequestStatus = 'idle' | 'loading' | 'success' | 'error';
export type PageStatus = 'idle' | 'loading' | 'empty' | 'success' | 'error';
/** Form draft of cadastrarProduto: the command input with every leaf still empty-able. */
export type ProdutoCadastroDraft = {
  details: {
    identification: { name: string | null };
    product: { unitOfMeasure: string | null };
    controleEstoque: { quantidadeMinima: number | null };
  };
};

const MODULE = 'controleEstoque';
const PAGE = 'produtos';
const BASE_PATH = '/controleEstoque';
const K = (id: string) => `ui.${MODULE}.${PAGE}.${id}`;

const STATE_MEMBER_BY_KEY: Record<string, keyof ControleEstoqueProdutosShared> = {
  [K('listaProdutos')]: 'listaProdutos',
  [K('filtroBuscaProdutos')]: 'filtroBuscaProdutos',
  [K('paginaProdutos')]: 'paginaProdutos',
  [K('produtoSelecionado')]: 'produtoSelecionado',
  [K('produtoCadastro')]: 'produtoCadastro',
  [K('produtoCadastrado')]: 'produtoCadastrado',
  [K('movimentacoesProduto')]: 'movimentacoesProduto',
  [K('listaProdutosHasMore')]: 'listaProdutosHasMore',
  [K('pageStatus')]: 'pageStatus',
  [K('loadStatus')]: 'loadStatus',
  [K('loadError')]: 'loadError',
  [K('cadastrarProdutoStatus')]: 'cadastrarProdutoStatus',
  [K('cadastrarProdutoError')]: 'cadastrarProdutoError',
  [K('scenary')]: 'scenary',
};
const STATE_KEYS = Object.keys(STATE_MEMBER_BY_KEY);
/** Members of one visit: reset on every entry, never hydrated from collabState. */
const TRANSIENT_MEMBERS = new Set<string>(["pageStatus", "loadStatus", "loadError", "cadastrarProdutoStatus", "cadastrarProdutoError", "scenary", "produtoCadastro"]);

/** Entry params: URL wins over localStorage, key `<module>.<pageId>.<param>`. */
const PERSISTED_PARAM_BY_STATE: Record<string, string> = {
  filtroBuscaProdutos: 'search',
  paginaProdutos: 'page',
  produtoSelecionado: 'produtoId',
};

function emptyProdutoCadastro(): ProdutoCadastroDraft {
  return { details: { identification: { name: null }, product: { unitOfMeasure: null }, controleEstoque: { quantidadeMinima: null } } };
}

function readEntryParam(name: string): string | null {
  const fromUrl = new URLSearchParams(window.location.search).get(name);
  if (fromUrl !== null) return fromUrl;
  try { return window.localStorage.getItem(`${MODULE}.${PAGE}.${name}`); } catch { return null; }
}

function toNumber(raw: string | null): number | null {
  if (raw === null || raw.trim() === '') return null;
  const value = Number(raw);
  return Number.isFinite(value) ? value : null;
}

export class ControleEstoqueProdutosShared extends StateLitElement {
  /** state listaProdutos — source load.produtos; organism listaProdutos */
  @property({ attribute: false }) listaProdutos: ProdutoLoad[] = [];
  /** state filtroBuscaProdutos — source entry.params.search (filter:listaProdutos, persisted) */
  @property({ attribute: false }) filtroBuscaProdutos: string | null = null;
  /** state paginaProdutos — source entry.params.page (filter:listaProdutos, persisted) */
  @property({ attribute: false }) paginaProdutos: number | null = null;
  /** state produtoSelecionado — source entry.params.produtoId (select:detalheProduto, persisted); holds the id */
  @property({ attribute: false }) produtoSelecionado: string | null = null;
  /** state produtoCadastro — source cadastrarProduto.input; form formularioProduto */
  @property({ attribute: false }) produtoCadastro: ProdutoCadastroDraft = emptyProdutoCadastro();
  /** state produtoCadastrado — source cadastrarProduto.produto */
  @property({ attribute: false }) produtoCadastrado: ProdutoCadastrarProduto | null = null;
  /** state movimentacoesProduto — set by abrirMovimentacoes; bound to no organism */
  @property({ attribute: false }) movimentacoesProduto: string | null = null;
  /** state listaProdutosHasMore — from load.hasMoreListaProdutos */
  @property({ attribute: false }) listaProdutosHasMore = false;
  /** state pageStatus — first load of the page */
  @property({ attribute: false }) pageStatus: PageStatus = 'idle';
  /** state loadStatus — request load */
  @property({ attribute: false }) loadStatus: RequestStatus = 'idle';
  /** state loadError — request load */
  @property({ attribute: false }) loadError: ErrorState = null;
  /** state cadastrarProdutoStatus — request cadastrarProduto */
  @property({ attribute: false }) cadastrarProdutoStatus: RequestStatus = 'idle';
  /** state cadastrarProdutoError — request cadastrarProduto */
  @property({ attribute: false }) cadastrarProdutoError: ErrorState = null;
  /** state scenary — the visible scene of the page; '' until the page shows its first scene */
  @property({ attribute: false }) scenary = '';

  /** derived for organism saldoAtual (summary): every loaded product, with its current balance */
  get saldoAtual(): ProdutoLoad[] {
    return this.listaProdutos;
  }

  /** derived for organism alertasSaldoBaixo (highlights): loaded products whose saldoAbaixoDoMinimo is true */
  get alertasSaldoBaixo(): ProdutoLoad[] {
    return this.listaProdutos.filter(item => item.details.controleEstoque.saldoAbaixoDoMinimo);
  }

  /** derived for organism detalheProduto (detail): the loaded product whose id is produtoSelecionado */
  get detalheProduto(): ProdutoLoad | null {
    return this.listaProdutos.find(item => item.id === this.produtoSelecionado) ?? null;
  }

  public connectedCallback(): void {
    super.connectedCallback();
    // data members only: the feedback, the scene and the draft of the previous visit never come back
    for (const key of STATE_KEYS) {
      if (TRANSIENT_MEMBERS.has(STATE_MEMBER_BY_KEY[key])) continue;
      const value = getState(key);
      if (value !== undefined) this.assignState(key, value);
    }
    this.resetVisit();
    subscribe([...STATE_KEYS], this);
    this.applyEntryParams();
    void this.runInitialLoad();
  }

  /** A fresh visit: statuses idle, errors null, first scene, empty draft. */
  private resetVisit(): void {
    this.publish('pageStatus', 'idle');
    this.publish('loadStatus', 'idle');
    this.publish('loadError', null);
    this.publish('cadastrarProdutoStatus', 'idle');
    this.publish('cadastrarProdutoError', null);
    this.publish('scenary', '');
    this.publish('produtoCadastro', emptyProdutoCadastro());
  }

  public disconnectedCallback(): void {
    unsubscribe([...STATE_KEYS], this);
    super.disconnectedCallback();
  }

  public handleIcaStateChange(key: string, value: any): void {
    const member = STATE_MEMBER_BY_KEY[key];
    if (!member) { super.handleIcaStateChange(key, value); return; }
    if (value === undefined) return;
    this.assignState(key, value);
    this.requestUpdate();
  }

  /** function load — Carregar produtos; calls controleEstoque.produtos.load; sets listaProdutos; updates produtoSelecionado */
  async load(): Promise<void> {
    const output = await this.query('controleEstoque.produtos.load', this.loadInput(this.paginaProdutos));
    if (!output) return;
    this.publish('listaProdutos', output.produtos);
    this.publish('listaProdutosHasMore', output.hasMoreListaProdutos);
    this.publish('paginaProdutos', output.pageListaProdutos);
    if (this.produtoSelecionado !== null && !output.produtos.some(item => item.id === this.produtoSelecionado)) this.publish('produtoSelecionado', null);
  }

  /** function filterListaProdutos — Filtrar produtos; reloads from page 1 and replaces listaProdutos; resets produtoSelecionado */
  async filterListaProdutos(search: string | null): Promise<void> {
    this.publish('filtroBuscaProdutos', search && search.trim() ? search : null);
    this.publish('paginaProdutos', 1);
    this.publish('produtoSelecionado', null);
    await this.load();
  }

  /** function loadMoreListaProdutos — Carregar mais produtos; fetches the next page and appends to listaProdutos */
  async loadMoreListaProdutos(): Promise<void> {
    if (!this.listaProdutosHasMore) return;
    const next = (this.paginaProdutos ?? 1) + 1;
    const output = await this.query('controleEstoque.produtos.load', this.loadInput(next));
    if (!output) return;
    this.publish('listaProdutos', [...this.listaProdutos, ...output.produtos]);
    this.publish('listaProdutosHasMore', output.hasMoreListaProdutos);
    this.publish('paginaProdutos', output.pageListaProdutos);
  }

  /** function cadastrarProduto — Cadastrar produto; command controleEstoque.produtos.cadastrarProduto; sets produtoCadastrado; reloads listaProdutos (A1 rule) */
  async cadastrarProduto(): Promise<void> {
    if (this.cadastrarProdutoStatus === 'loading') return;
    const draft = this.produtoCadastro;
    const name = draft.details.identification.name;
    const unitOfMeasure = draft.details.product.unitOfMeasure;
    const quantidadeMinima = draft.details.controleEstoque.quantidadeMinima;
    if (!name || !unitOfMeasure || quantidadeMinima === null) {
      const missing = [
        name ? '' : 'details.identification.name',
        unitOfMeasure ? '' : 'details.product.unitOfMeasure',
        quantidadeMinima !== null ? '' : 'details.controleEstoque.quantidadeMinima',
      ].filter(Boolean);
      this.publish('cadastrarProdutoError', { code: 'client.requiredMissing', message: '', details: { stateKeys: missing.map(path => `${K('produtoCadastro')}.${path}`) } });
      this.publish('cadastrarProdutoStatus', 'error');
      return;
    }
    const input: Input<'controleEstoque.produtos.cadastrarProduto'> = {
      details: { identification: { name }, product: { unitOfMeasure }, controleEstoque: { quantidadeMinima } },
    };
    this.publish('cadastrarProdutoStatus', 'loading');
    this.publish('cadastrarProdutoError', null);
    try {
      const response = await runBlockingUiAction(signal => execBff<Output<'controleEstoque.produtos.cadastrarProduto'>>('controleEstoque.produtos.cadastrarProduto', input, { mode: 'blocking', signal }));
      if (!response) {
        this.publish('cadastrarProdutoError', { code: 'client.unexpected', message: '', details: { name: 'aborted' } });
        this.publish('cadastrarProdutoStatus', 'error');
        return;
      }
      if (!response.ok || !response.data) {
        this.publish('cadastrarProdutoError', response.error ?? { code: 'client.unexpected', message: '' });
        this.publish('cadastrarProdutoStatus', 'error');
        return;
      }
      this.publish('produtoCadastrado', response.data.produto);
      this.publish('produtoCadastro', emptyProdutoCadastro());
      await this.load();
      this.publish('produtoSelecionado', response.data.produto.id);
      this.publish('cadastrarProdutoStatus', 'success');
    } catch (error) {
      this.publish('cadastrarProdutoError', { code: 'client.unexpected', message: '', details: { name: error instanceof Error ? error.name : 'unknown' } });
      this.publish('cadastrarProdutoStatus', 'error');
    }
  }

  /** function selecionarProduto — Selecionar produto; sets produtoSelecionado when the id is in listaProdutos */
  selecionarProduto(produtoId: string | null): void {
    this.resetCommandResults();
    if (produtoId === null) { this.publish('produtoSelecionado', null); return; }
    if (!this.listaProdutos.some(item => item.id === produtoId)) {
      this.publish('loadError', { code: 'client.selectionInvalid', message: '', details: { stateKey: K('produtoSelecionado'), value: produtoId } });
      return;
    }
    this.publish('produtoSelecionado', produtoId);
  }

  /** function abrirMovimentacoes — Abrir movimentações; navigates to movimentacoes carrying produtoId */
  abrirMovimentacoes(): void {
    if (this.produtoSelecionado === null) {
      this.publish('loadError', { code: 'client.preconditionMissing', message: '', details: { stateKeys: [K('produtoSelecionado')] } });
      return;
    }
    this.publish('movimentacoesProduto', this.produtoSelecionado);
    auraNavigate(`${BASE_PATH}/movimentacoes?produtoId=${encodeURIComponent(this.produtoSelecionado)}`, { basePath: BASE_PATH });
  }

  /** setter for the scene the page shows; the pages decide which scenes exist */
  setScenario(value: string): void {
    this.resetCommandResults();
    this.publish('scenary', value);
  }

  /** setter for the form draft of formularioProduto */
  setProdutoCadastro(value: ProdutoCadastroDraft): void {
    this.resetCommandResults();
    this.publish('produtoCadastro', value);
  }

  /** The person changed what the commands act on (a form, the selection, the scene): their old result goes away. */
  private resetCommandResults(): void {
    this.publish('cadastrarProdutoStatus', 'idle');
    this.publish('cadastrarProdutoError', null);
  }

  private loadInput(page: number | null): Input<'controleEstoque.produtos.load'> {
    return {
      ...(this.filtroBuscaProdutos ? { search: this.filtroBuscaProdutos } : {}),
      ...(page !== null ? { page } : {}),
    };
  }

  private async query<R extends 'controleEstoque.produtos.load'>(route: R, input: Input<R>): Promise<Output<R> | null> {
    if (this.loadStatus === 'loading') return null;
    this.publish('loadStatus', 'loading');
    this.publish('loadError', null);
    try {
      const response = await execBff<Output<R>>(route, input, { mode: 'silent' });
      if (!response.ok || !response.data) {
        this.publish('loadError', response.error ?? { code: 'client.unexpected', message: '' });
        this.publish('loadStatus', 'error');
        return null;
      }
      this.publish('loadStatus', 'success');
      return response.data;
    } catch (error) {
      this.publish('loadError', { code: 'client.unexpected', message: '', details: { name: error instanceof Error ? error.name : 'unknown' } });
      this.publish('loadStatus', 'error');
      return null;
    }
  }

  private async runInitialLoad(): Promise<void> {
    this.publish('pageStatus', 'loading');
    await this.load();
    this.publish('pageStatus', this.loadStatus === 'error' ? 'error' : this.listaProdutos.length ? 'success' : 'empty');
  }

  private applyEntryParams(): void {
    const search = readEntryParam('search');
    const page = toNumber(readEntryParam('page'));
    const produtoId = readEntryParam('produtoId');
    if (search !== null) this.publish('filtroBuscaProdutos', search);
    if (page !== null) this.publish('paginaProdutos', page);
    if (produtoId !== null) this.publish('produtoSelecionado', produtoId);
  }

  private publish<M extends keyof this & string>(member: M, value: this[M]): void {
    (this as Record<string, unknown>)[member] = value;
    setState(K(member), value);
    const param = PERSISTED_PARAM_BY_STATE[member];
    if (param) {
      try {
        const storageKey = `${MODULE}.${PAGE}.${param}`;
        if (value === null || value === undefined) window.localStorage.removeItem(storageKey);
        else window.localStorage.setItem(storageKey, String(value));
      } catch { /* storage unavailable: the URL still works */ }
    }
  }

  private assignState(key: string, value: unknown): void {
    const member = STATE_MEMBER_BY_KEY[key];
    if (member) (this as Record<string, unknown>)[member] = value;
  }
}
